import React, { useContext } from 'react';
import { TripContext } from '../context/TripContext';

const TripSummary = () => {
  const { families, expenses } = useContext(TripContext);

  const totalPeople = families.reduce((sum, fam) => sum + fam.members.length + 1, 0);
  const totalExpense = expenses.reduce((sum, exp) => sum + parseFloat(exp.amount), 0);
  const perPersonCost = totalPeople ? totalExpense / totalPeople : 0;

  const summary = families.map(family => {
    const memberCount = family.members.length + 1;
    const share = memberCount * perPersonCost;
    const paid = expenses
      .filter(exp => exp.paidBy === family.head)
      .reduce((sum, exp) => sum + parseFloat(exp.amount), 0);
    return {
      family: family.head,
      paid,
      share,
      balance: parseFloat((paid - share).toFixed(2)),
    };
  });

  // Split into givers (owe money) and receivers (to get money)
  let givers = summary.filter(s => s.balance < 0).map(s => ({ ...s, balance: -s.balance }));
  let receivers = summary.filter(s => s.balance > 0).map(s => ({ ...s }));

  const settlements = [];

  // Settle balances
  for (let giver of givers) {
    while (giver.balance > 0 && receivers.length) {
      let receiver = receivers[0];
      const amount = Math.min(giver.balance, receiver.balance);

      settlements.push({
        from: giver.family,
        to: receiver.family,
        amount: amount.toFixed(2),
      });

      giver.balance -= amount;
      receiver.balance -= amount;

      if (receiver.balance <= 0.01) receivers.shift(); // remove settled receiver
    }
  }

  const styles = {
    container: {
      marginTop: '30px',
      border: '1px solid #ccc',
      padding: '15px',
      borderRadius: '8px',
      backgroundColor: '#f9f9f9',
    },
    section: { marginBottom: '20px' },
    list: { marginLeft: '20px' },
    settlement: { marginBottom: '5px' },
  };

  return (
    <div style={styles.container}>
      <h3>Trip Summary</h3>

      <div style={styles.section}>
        <p><strong>Total Expense:</strong> ₹{totalExpense.toFixed(2)}</p>
        <p><strong>Per Person Share:</strong> ₹{perPersonCost.toFixed(2)}</p>
      </div>

      <div style={styles.section}>
        <h4>Family Contributions:</h4>
        <ul style={styles.list}>
          {summary.map((item, index) => (
            <li key={index}>
              <strong>{item.family}</strong> paid ₹{item.paid.toFixed(2)}, should pay ₹{item.share.toFixed(2)} ⇒
              {item.balance > 0
                ? ` gets ₹${item.balance.toFixed(2)}`
                : ` owes ₹${(-item.balance).toFixed(2)}`}
            </li>
          ))}
        </ul>
      </div>

      <div style={styles.section}>
        <h4>Settlements:</h4>
        {settlements.length === 0 ? (
          <p>No settlements needed. Everyone has paid their share.</p>
        ) : (
          <ul style={styles.list}>
            {settlements.map((s, index) => (
              <li key={index} style={styles.settlement}>
                <strong>{s.from}</strong> pays ₹{s.amount} to <strong>{s.to}</strong>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default TripSummary;
